fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Pre-allocate a new Vec with the same capacity as the input list
    let len = list.len();
    let mut new_list = Vec::with_capacity(len);

    // Append the tail of the input list (from n to end)
    new_list.extend_from_slice(&list[n..]);

    // Append the head of the input list (from 0 to n)
    new_list.extend_from_slice(&list[..n]);

    new_list
}

